      "line_hint": "Theorem 1 and restated version, conclusions (1) and (2)."
    },
    {
      "claim": "The Fourier coefficients of f_w^{(j)} are real ... consequently A_w^{(j)}(s) ∈ H_K ∩ R.",
      "issue": "The algebraic part A defined using (2πi)^s and Ω_K is not automatically real; complex conjugation may act nontrivially on the transcendental factors. The claim of reality without further justification is incorrect.",
      "line_hint": "Proof sketch, Step 4, around 'Reality'."
    }
  ],
  "equation_issues": [
    {
      "equation": "q^2(D) := \\bigl(L_5/L_3\\bigr)^2 / \\bigl((2\\pi^2/N)^2 L_5/L_3 \\bigr)",
      "issue": "Undefined symbol N; ambiguous parentheses; the expression does not correspond to the later definition of q(D,s5,s3) and contains an unexplained power of π. The equation is ill-formed."
    },
    {
      "equation": "P\\bigl(L(f_{w_1}^{(j)}, s_1)_{j=1}^{h_K}\\, ;\\, L(f_{w_2}^{(j)}, s_2)_{j=1}^{h_K}\\bigr) \\;\\in\\; \\Q^{\\times}",
      "issue": "This directly evaluated polynomial includes transcendental factors (2πi, Ω_K, Γ-values) that are not divided out. The statement is mathematically false unless the polynomial is understood to encode a ratio. The remark 'after cancellation of the universal periods' in the abstract is missing here."
    },
    {
      "equation": "s_1 + s_2 \\; = \\; \\frac{w_1 + w_2}{2}",
      "issue": "The stratum condition is not needed for the cancellation of (2πi) in the canonical cross-ratio example used later, and its role is misrepresented in the proof sketch; the condition alone does not guarantee rational evaluation without division by periods."
    },
    {
      "equation": "a_p(f_{2m+1}) \\; = \\; D_m\\bigl(a_p(f_3), p\\bigr)",
      "issue": "The formula is stated without a proper reference or derivation. The connection to Dickson polynomials for CM forms is plausible but not justified for all such newforms; the citation of Hecke 1937 and Schütt 2008 does not explicitly support this exact statement."
    }
  ],
  "scope_overclaims": [
    {
      "claim": "The architecture used to prove Theorem 1 extends, in principle, to an arbitrary tensor category of motives admitting a Damerell-style period factorisation.",
      "actual_scope": "No evidence is given for such a sweeping extension; the claim is purely speculative."
    },
    {
      "claim": "the plan is winnable in 4–8 weeks of symbolic computation",
      "actual_scope": "This is an unfounded time estimate for solving a major open problem; it undermines scientific credibility."
    },
    {
      "claim": "Every Galois-equivariant homogeneous polynomial ... which is balanced ... is rational, after cancellation of the universal periods ... unifies and refines several conjectures (C‑1')",
      "actual_scope": "The conjectures C‑1' are not defined, and the unification claim is not substantiated. The numeric verification on fifty anchors does not prove the structural result for all discriminants."
    },
    {
      "claim": "The denominator of the rational ... divides Nm_{K/Q}(disc O_K) = |D|^2, up to small prime powers",
      "actual_scope": "The integrality input from Kings‑Sprang concerns integers in the Hilbert class field, not O_K, so the denominator bound is unjustified; the actual denominator could be much larger."
    }
  ],
  "missing_citations": [
    {
      "claim": "unifies and refines several conjectures (C-1') that were empirically observed",
      "needs_cite": "A reference or definition for the conjectures C-1' is required."
    },
    {
      "claim": "q^2 = r_5^2 / r_3^2 holds across eight independent h_K = 2 anchors",
      "needs_cite": "The symbols r_5, r_3 are not defined in the paper; a prior source is missing."
    },
    {
      "claim": "Kazakov-Zheng bootstrap [KazakovZheng2024]",
      "needs_cite": "This reference is not verifiable; at minimum an arXiv ID is needed."
    },
    {
      "claim": "Brennecke 2025 [Brennecke2025] for the leading-order analytic free energy",
      "needs_cite": "No identifiable publication; the reference appears fabricated or unavailable."
    },
    {
      "claim": "Gaiotto 2025 [Gaiotto2025] extends this dictionary...",
      "needs_cite": "Unpublished or non-existent; a proper citation is missing."
    },
    {
      "claim": "Hecke recursion ... a_p(f_{2m+1}) = D_m(a_p(f_3), p)",
      "needs_cite": "A standard reference for the Dickson polynomial relation in the context of CM newforms is needed (e.g., relation to Chebyshev polynomials)."
    }
  ],
  "minor_polish": [
    "\\subjclass is undefined; should be \\subjclass or \\subjclass?",
